"""Positive evidence for currency receipts and skin-unlock continuation."""
import base64
from functools import lru_cache
import cv2
import numpy as np

@lru_cache(maxsize=32)
def _glyph(encoded, height):
    raw = cv2.imdecode(np.frombuffer(base64.b64decode(encoded), np.uint8), 0)
    return cv2.resize(raw, (max(2, round(raw.shape[1]*height/720)),
                            max(2, round(raw.shape[0]*height/720))))

def _find(frame, encoded, bounds, white=True, factor=1.):
    h, w = frame.shape[:2]
    x1, y1, x2, y2 = bounds
    left, top = round(w*x1), round(h*y1)
    crop = frame[top:round(h*y2), left:round(w*x2)]
    if not crop.size:
        return None
    image = (np.all(crop > 205, axis=2).astype(np.uint8)*255 if white
             else cv2.cvtColor(crop, cv2.COLOR_RGB2GRAY))
    glyph = _glyph(encoded, round(h*factor))
    if any(image.shape[i] < glyph.shape[i] for i in (0, 1)):
        return None
    _, score, _, loc = cv2.minMaxLoc(cv2.matchTemplate(image, glyph, cv2.TM_CCOEFF_NORMED))
    if score < .9:
        return None
    return left + loc[0] + glyph.shape[1]/2, top + loc[1] + glyph.shape[0]/2

def _valid(frame):
    return isinstance(frame, np.ndarray) and frame.ndim == 3 and frame.shape[2] == 3

def bling_receipt(frame):
    if not _valid(frame):
        return False
    h, w = frame.shape[:2]
    # Both title and rainbow token must be on a full-screen purple/cyan receipt.
    margin = frame[round(h*.25):round(h*.9), :round(w*.12)].astype(np.float32)
    backdrop = (margin[:,:,2] > margin[:,:,0]*1.25) & (margin[:,:,2] > margin[:,:,1]*1.05)
    if not backdrop.size or backdrop.mean() < .8:
        return False
    if _find(frame, BLING_TITLE, (.35,.08,.65,.25)) is None:
        return False
    return any(_find(frame, token, (.4,.4,.65,.75), white=False, factor=factor) is not None
               for token in (BLING_TOKEN, CURRENT_BLING_TOKEN)
               for factor in (1., .94, 1.06))

def skin_receipt_continue_position(frame):
    if not _valid(frame):
        return None
    if (_find(frame, CURRENT_SKIN, (.55,0,.8,.1)) is None or
            _find(frame, REMAINING, (.65,.9,.95,1)) is None):
        return None
    position = _find(frame, CONTINUE, (.46,.8,.69,.92))
    if position is None:
        return None
    h, w = frame.shape[:2]
    button = frame[round(h*.825):round(h*.89), round(w*.49):round(w*.665)]
    blue = (button[:,:,0] < 85) & (button[:,:,1] > 65) & (button[:,:,2] > 170)
    return position if blue.size and blue.mean() > .35 else None

BLING_TITLE = ''
BLING_TOKEN = ''
CURRENT_SKIN = ''
REMAINING = ''
CONTINUE = ''


def locked_skin_receipt(frame):
    if not _valid(frame):
        return False
    if (_find(frame, REMAINING, (.65,.9,.95,1)) is None or
            _find(frame, REQUIRED_BRAWLER, (.62,.6,.94,.7)) is None):
        return False
    h, w = frame.shape[:2]
    card = frame[round(h*.61):round(h*.82), round(w*.66):round(w*.93)]
    # A receipt for a locked brawler has no equipment/continuation buttons.
    return bool(card.size and (np.all(card < 65, axis=2)).mean() > .6)

REQUIRED_BRAWLER = ''


def sequence_receipt(frame):
    """A remaining-items counter on the full-screen blue reward reveal."""
    if not _valid(frame) or _find(frame, REMAINING, (.65,.9,.95,1)) is None:
        return False
    h, w = frame.shape[:2]
    # Require the reveal background on both sides, away from the reward icon.
    for left, right in [(.03,.22),(.78,.97)]:
        margin = frame[round(h*.2):round(h*.85),round(w*left):round(w*right)].astype(np.float32)
        blue = (margin[:,:,2] > margin[:,:,0]*1.3) & (margin[:,:,2] > margin[:,:,1]*1.12)
        if not blue.size or blue.mean() < .85:
            return False
    item = frame[round(h*.32):round(h*.78),round(w*.34):round(w*.66)]
    dark = np.all(item < 65, axis=2)
    # The receipt must contain an item, rather than an empty loading screen.
    return bool(dark.size and .025 < dark.mean() < .6)


def summary_receipt(frame):
    if not _valid(frame) or _find(frame, SUMMARY_TITLE, (.35,.04,.65,.2), white=False) is None:
        return False
    h, w = frame.shape[:2]
    footer = frame[round(h*.8):round(h*.96),round(w*.08):round(w*.92)].astype(np.float32)
    blue = (footer[:,:,2] > footer[:,:,0]*1.35) & (footer[:,:,2] > footer[:,:,1]*1.2)
    return bool(blue.size and blue.mean() > .9)

SUMMARY_TITLE = ''

# Current upright diamond token on the full-screen BLING receipt.
CURRENT_BLING_TOKEN = ''
